export default function (pi: ExtensionAPI) {
  // Inject tGD rules at session start
  pi.on("session_start", async (_event, ctx) => {
    ctx.ui.notify("tGD workflow loaded. Use /tgd-map to begin.", "info");
  });

  // Register 7 lifecycle slash commands
  for (const [name, description] of [
    ["tgd-map", "Map — scan and understand the existing project context before making changes"],
    ["tgd-define", "Start spec-driven development — write a structured specification before writing code"],
    ["tgd-plan", "Plan — decompose specs into small, verifiable tasks with acceptance criteria"],
    ["tgd-develop", "Develop — implement with fresh subagents per task and two-stage review"],
    ["tgd-verify", "Verify — prove it works with debugging and test pyramid"],
    ["tgd-review", "Review before merge — improve code health"],
    ["tgd-release", "Release to production — faster is safer"],
  ] as [string, string][]) {
    pi.registerCommand(name, {
      description,
      handler: async (_args, ctx) => {
        const prompt = tgdPrompts[name];
        if (prompt) {
          ctx.ui.notify(`Running ${name}...`, "info");
          pi.sendUserMessage(prompt);
        }
      },
    });
  }
}
